package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SimpleType._narrow
 */
public class SimpleType__narrow_TriageGen2Test {

    /**
     * Helper method to access the protected _narrow method via reflection.
     */
    @SuppressWarnings("unchecked")
    private <T extends JavaType> T invokeNarrow(T type, Class<?> subclass) throws Exception {
        Method method = SimpleType.class.getDeclaredMethod("_narrow", Class.class);
        method.setAccessible(true);
        return (T) method.invoke(type, subclass);
    }

    @Test
    public void testNarrow_SameClass_ReturnsThis() throws Exception {
        TypeFactory<?> tf = TypeFactory.defaultInstance();
        SimpleType type = tf.constructType(String.class);

        // When subclass is the same as the current class, it should return 'this'
        JavaType result = invokeNarrow(type, String.class);

        Assert.assertSame("Should return the exact same instance when classes match", type, result);
    }

    @Test
    public void testNarrow_DifferentClass_ReturnsNewSimpleType() throws Exception {
        TypeFactory<?> tf = TypeFactory.defaultInstance();
        SimpleType type = tf.constructType(Object.class);

        // When subclass is different, it should return a new SimpleType instance
        JavaType result = invokeNarrow(type, String.class);

        Assert.assertNotSame("Should return a new instance when classes differ", type, result);
        Assert.assertNotNull(result);
        Assert.assertTrue("Result should be a SimpleType", result instanceof SimpleType);

        // Verify the new type has the correct class
        SimpleType resultAsSimple = (SimpleType) result;
        Assert.assertEquals(String.class, resultAsSimple.getRawClass());
    }

    @Test
    public void testNarrow_WithHierarchy() throws Exception {
        TypeFactory<?> tf = TypeFactory.defaultInstance();
        // Create a type for Number.class
        SimpleType type = tf.constructType(Number.class);

        // Narrow to Integer.class
        JavaType result = invokeNarrow(type, Integer.class);

        Assert.assertNotSame(type, result);
        Assert.assertEquals(Integer.class, ((SimpleType) result).getRawClass());
    }

    @Test
    public void testNarrow_NullSubclass_ThrowsException() throws Exception {
        TypeFactory<?> tf = TypeFactory.defaultInstance();
        SimpleType type = tf.constructType(String.class);

        try {
            invokeNarrow(type, null);
            Assert.fail("Expected NullPointerException due to _class == subclass check or internal logic");
        } catch (Exception e) {
            // The exception is wrapped in InvocationTargetException by reflection
            Assert.assertTrue(e.getCause() instanceof NullPointerException);
        }
    }
}
